-- Pictures for the COLORS words, stored in answer_items.metadata.image (a base64 data URI) next to the existing emoji.
-- The question snapshot keeps only the item id; GET /api/v1/media/answer-items/{id}/image serves the picture, and an item
-- without metadata.image keeps showing its emoji. Merging with || keeps every other tag of the item (emoji, category, ...).
-- Idempotent: running it again writes the same value. Files: 512x512 webp, one solid colour each.

UPDATE answer_items
SET metadata = metadata || jsonb_build_object('image', 'data:image/webp;base64,'), updated_at = now()
WHERE code = 'COLORS_BLACK';

UPDATE answer_items
SET metadata = metadata || jsonb_build_object('image', 'data:image/webp;base64,'), updated_at = now()
WHERE code = 'COLORS_BLUE';

